class FizzBuzz
{
    static void Main()
    {
        for (int i = 1; i <= 30; i++)
        {
            switch (i % 15)
            {
                case 0: Console.Write("FizzBuzz"); break;
                case 3: case 6: case 9: case 12: Console.Write("Fizz"); break;
                case 5: case 10: Console.Write("Buzz"); break;
                default: Console.Write(i); break;
            }
            Console.Write(' ');
        }
    }
}

class Sieve
{
    const int Limit = 200;

    static void Main()
    {
        bool[] composite = new bool[Limit];
        int count = 0;
        for (int n = 2; n < Limit; n++)
        {
            if (composite[n]) continue;
            Console.Write(n);
            Console.Write(' ');
            count++;
            for (int m = n * n; m < Limit && m > 0; m += n)
                composite[m] = true;
        }
        Console.WriteLine();
        Console.WriteLine($"{count} primes below {Limit}");
    }
}

class Sorting
{
    static void InsertionSort(int[] a)
    {
        for (int i = 1; i < a.Length; i++)
        {
            int key = a[i];
            int j = i - 1;
            while (j >= 0 && a[j] > key)
            {
                a[j + 1] = a[j];
                j--;
            }
            a[j + 1] = key;
        }
    }

    static void Print(string label, int[] a)
    {
        Console.Write(label);
        foreach (int x in a)
            Console.Write($" {x}");
        Console.WriteLine();
    }

    static void Main()
    {
        int[] numbers = { 42, -7, 19, 0, 3, 1000, -250, 8, 8, 77 };
        Print("before:", numbers);
        InsertionSort(numbers);
        Print("after: ", numbers);
        Console.WriteLine($"min {numbers[0]}, max {numbers[numbers.Length - 1]}");
    }
}

// A Sierpinski triangle: a pixel is lit where x AND y has no bits set
class Sierpinski
{
    const int Size = 256;

    static void Main()
    {
        Screen.Clear();
        for (int y = 0; y < Size; y++)
        {
            Screen.MoveTo(192, y + 112);
            for (int x = 0; x < Size; x++)
            {
                int colour = (x & y) == 0 ? Screen.Rgb(x, y, 255 - x) : 0;
                Screen.Put(colour);
            }
        }
        Console.Write("Sierpinski, drawn");
    }
}

class Node
{
    int value;
    Node left, right;

    public Node(int v) { value = v; }

    public void Insert(int v)
    {
        if (v < value)
        {
            if (left == null) left = new Node(v); else left.Insert(v);
        }
        else
        {
            if (right == null) right = new Node(v); else right.Insert(v);
        }
    }

    public void Print()
    {
        if (left != null) left.Print();
        Console.Write($"{value} ");
        if (right != null) right.Print();
    }
}

class Program
{
    static void Main()
    {
        Node tree = new Node(50);
        int[] values = { 30, 70, 20, 40, 60, 80, 35, 65, 10 };
        foreach (int v in values) tree.Insert(v);
        tree.Print();
        Console.WriteLine();

        for (int i = 0; i < 20000; i++) new Node(i);
        Console.WriteLine("20000 throwaway nodes later,");
        Console.WriteLine("the collector kept the tree:");
        tree.Print();
    }
}

// Draw with the arrow keys; space changes the colour.
// Switch on Max speed and use the keypad.
class Sketch
{
    static int[] palette = { 0xFFFF, 0xF800, 0x07E0, 0x001F, 0xFFE0 };

    static void Main()
    {
        int x = 320, y = 240, colour = 0;
        Console.WriteLine("Arrow keys draw,");
        Console.WriteLine("space changes colour");
        while (true)
        {
            int keys = Keys.Read();
            if ((keys & Keys.Left) != 0 && x > 0) x--;
            if ((keys & Keys.Right) != 0 && x < 639) x++;
            if ((keys & Keys.Up) != 0 && y > 0) y--;
            if ((keys & Keys.Down) != 0 && y < 479) y++;
            if ((keys & Keys.Space) != 0) colour = (colour + 1) % palette.Length;
            Screen.Plot(x, y, palette[colour]);
        }
    }
}
